css_extra:
section[data-name="Hero"].tone-light { --s-bg:#241F1F;--fg:#FFFFFF;--fg2:#E9DCCD;--fg3:#CDBFB0;--surface:#2E2716;--alt:#2E2716;--rule:rgba(233,220,205,.22);--accent:#C2A76C;--fine:#C2A76C;--turn:#C2A76C;--btn-bg:#C2A76C;--btn-fg:#241F1F;color:var(--fg); }
.tone-dark { --turn:#C2A76C; }
.tone-light, .tone-panel, .tone-card { --btn-bg:#C2A76C;--btn-fg:#241F1F; }
.tick i { background: url(assets/crown.png) center/17px auto no-repeat !important; border-radius: 0; width: 22px; }
.tick i svg { display: none; }
section[data-name="Pricing"] i { background: url(assets/crown.png) center/20px auto no-repeat !important; border-radius:0 !important; }
section[data-name="Pricing"] i svg { display: none; }
span.acc[style*="inline-flex"] { color:#C2A76C; }
.tone-light [data-name="Story"], .tone-light [data-name="Review"], .tone-panel [data-name="Story"], .tone-panel [data-name="Review"] { border:1px solid #D9C69C; box-shadow:none; }
.tone-dark .card[data-name="Story"], .tone-dark [data-name="Review"] { border:1px solid #C2A76C; }
[data-name="Backdrop"] { background:none !important; border:1.5px solid #C2A76C; }
[data-name="Watermark"] svg { opacity:.09; }
.tone-dark [data-name="Watermark"] svg, section[data-name="Hero"] [data-name="Watermark"] svg { opacity:.12; }
[data-name="Story"] > div:last-child > div:first-child { flex-wrap:wrap; gap:6px 12px; }
.hero-s > div:last-child { left:-46px !important; bottom:40px !important; }
